package daemon

import (
	"context"
	"net/http"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/zydo/subactl/api"
	"github.com/zydo/subactl/internal/audit"
	"github.com/zydo/subactl/internal/backend"
	"github.com/zydo/subactl/internal/telemetry"
)

// Event types of the control plane, all generated by subactld from
// structured data. None carries free text from a child.
const (
	eventBeacon          = "BEACON"           // a progress beacon; kept for the trace, not broadcast
	eventDone            = "DONE"             // a child reported that its task is finished
	eventIdleDone        = "IDLE_DONE"        // a child is done but still alive
	eventStalled         = "STALLED"          // a working child has sent no beacon for a while
	eventResizeRequested = "RESIZE_REQUESTED" // a child asks its parent for a larger envelope
)

// Progress states.
const (
	stateWorking       = "working"
	stateAwaitingInput = "awaiting_input"
	stateDone          = "done"
)

const (
	maxInbox  = 256 // messages kept per lease
	maxReason = 500 // bytes of free text an ancestor may send
)

// inbox is the control-message queue of one lease. Only subactld itself
// and the lease's ancestors can put a message in it.
type inbox struct {
	msgs []api.InboxMessage
	seq  int64
	subs map[chan api.InboxMessage]struct{}
}

// beacon is the last progress report of a lease and what was already said
// about its idleness.
type beacon struct {
	state        string
	at           time.Time
	saidStalled  bool
	saidIdleDone bool
}

// control is the manager's control-plane state.
type control struct {
	mu      sync.Mutex
	inboxes map[api.LeaseID]*inbox
	beacons map[api.LeaseID]*beacon
	// scratch lists, per parent, the reaped children whose scratch
	// directories are kept until that parent ends.
	scratch map[api.LeaseID][]api.LeaseID
}

func newControl() *control {
	return &control{
		inboxes: map[api.LeaseID]*inbox{}, beacons: map[api.LeaseID]*beacon{},
		scratch: map[api.LeaseID][]api.LeaseID{},
	}
}

// deliver puts a control message in a lease's inbox. source is "subactld"
// or the id of the ancestor that sent it; the adapter shows it verbatim,
// so a message cannot claim another origin.
func (m *Manager) deliver(to api.LeaseID, typ, source, reason string, deadline *time.Time) {
	c := m.ctl
	c.mu.Lock()
	in := c.inboxes[to]
	if in == nil {
		in = &inbox{subs: map[chan api.InboxMessage]struct{}{}}
		c.inboxes[to] = in
	}
	in.seq++
	msg := api.InboxMessage{Seq: in.seq, Type: typ, Source: source, Reason: reason, Deadline: deadline, At: time.Now()}
	in.msgs = append(in.msgs, msg)
	if len(in.msgs) > maxInbox {
		in.msgs = in.msgs[len(in.msgs)-maxInbox:]
	}
	for ch := range in.subs {
		select {
		case ch <- msg:
		default: // a reader that has fallen behind picks it up from the backlog on reconnect
		}
	}
	c.mu.Unlock()
	// The trace shows what was injected into the agent's conversation.
	m.obs.mu.Lock()
	if l := m.obs.lease(to); len(l.events) < maxEvents {
		l.events = append(l.events, api.Event{Type: "INBOX", Lease: to, At: msg.At, Data: map[string]any{"type": typ, "source": source}})
	}
	m.obs.mu.Unlock()
}

// Inbox streams a lease's control messages: what is queued, then what
// arrives. Only the lease itself may read its inbox.
func (m *Manager) Inbox(c Caller, id api.LeaseID) (<-chan api.InboxMessage, func(), error) {
	ls, err := m.resolve(c, id)
	if err != nil {
		return nil, nil, err
	}
	if c.Lease != ls.ID {
		return nil, nil, apiErr(http.StatusForbidden, api.ErrOutOfSubtree, "an inbox can only be read by its own lease")
	}
	ctl := m.ctl
	ch := make(chan api.InboxMessage, maxInbox)
	ctl.mu.Lock()
	in := ctl.inboxes[ls.ID]
	if in == nil {
		in = &inbox{subs: map[chan api.InboxMessage]struct{}{}}
		ctl.inboxes[ls.ID] = in
	}
	for _, msg := range in.msgs {
		ch <- msg
	}
	in.subs[ch] = struct{}{}
	ctl.mu.Unlock()
	var once sync.Once
	return ch, func() {
		once.Do(func() {
			ctl.mu.Lock()
			delete(in.subs, ch)
			ctl.mu.Unlock()
		})
	}, nil
}

func validMessageType(t string) bool {
	switch t {
	case api.MsgTerminateRequested, api.MsgNearLimit, api.MsgResized, api.MsgCapacityShrunk:
		return true
	}
	return false
}

// cleanText keeps printable text only and bounds its length, so that a
// reason cannot smuggle control characters into a terminal or a prompt
// template.
func cleanText(s string, max int) string {
	s = strings.Map(func(r rune) rune {
		if r == '\n' || r == '\t' {
			return ' '
		}
		if r < 0x20 || r == 0x7f {
			return -1
		}
		return r
	}, s)
	if len(s) > max {
		s = s[:max]
	}
	return strings.TrimSpace(s)
}

// Notify lets a planner send a control message down to a descendant. A
// node cannot notify itself, a sibling or an ancestor.
func (m *Manager) Notify(c Caller, id api.LeaseID, req api.NotifyRequest) error {
	ls, err := m.resolve(c, id)
	if err != nil {
		return err
	}
	if ls.ID == c.Lease {
		return apiErr(http.StatusForbidden, api.ErrOutOfSubtree, "a node cannot put messages in its own inbox")
	}
	if !validMessageType(req.Type) {
		return invalid("type", "TERMINATE_REQUESTED, NEAR_LIMIT, RESIZED or CAPACITY_SHRUNK", api.MsgNearLimit, "unknown message type %q; the set is closed", req.Type)
	}
	if ls.State == api.StateReaped || ls.State == api.StateReaping {
		return apiErr(http.StatusConflict, api.ErrConflict, "lease %s has ended", ls.ID)
	}
	source := "operator"
	if c.Lease != "" {
		source = string(c.Lease)
	}
	m.deliver(ls.ID, req.Type, source, cleanText(req.Reason, maxReason), nil)
	return nil
}

// scratchDir returns the lease's scratch directory, or "" when the backend
// has none.
func (m *Manager) scratchDir(id api.LeaseID) string {
	if s, ok := m.be.(backend.Scratcher); ok {
		return s.ScratchDir(id)
	}
	return ""
}

// validResult checks the one string a child may hand up: a path inside its
// own scratch directory, made of plain characters. The planner gets the
// path only; the file's content is never inlined into an event.
func validResult(scratch, p string) bool {
	if p == "" || scratch == "" || len(p) > 1024 {
		return false
	}
	for _, r := range p {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '/', r == '.', r == '_', r == '-':
		default:
			return false
		}
	}
	clean := filepath.Clean(p)
	rel, err := filepath.Rel(scratch, clean)
	return err == nil && filepath.IsAbs(clean) && rel != "." && !strings.HasPrefix(rel, "..")
}

// Progress records a beacon from a lease's harness adapter. It costs no
// LLM call: the adapter reports from its hooks.
func (m *Manager) Progress(c Caller, id api.LeaseID, req api.ProgressRequest) error {
	ls, err := m.resolve(c, id)
	if err != nil {
		return err
	}
	if c.Lease != ls.ID {
		return apiErr(http.StatusForbidden, api.ErrOutOfSubtree, "a beacon can only be reported by its own lease")
	}
	switch req.State {
	case stateWorking, stateAwaitingInput, stateDone:
	default:
		return invalid("state", "working, awaiting_input or done", stateWorking, "unknown state %q", req.State)
	}
	if req.Result != "" {
		if req.State != stateDone {
			return invalid("result", "only with state done", "", "a result path is handed over when the task is done")
		}
		if !validResult(m.scratchDir(ls.ID), req.Result) {
			return invalid("result", "a path inside the lease's scratch directory, of letters, digits and / . _ -",
				filepath.Join(m.scratchDir(ls.ID), "result.md"), "the result must be a file in the lease's own scratch directory")
		}
	}
	now := time.Now()
	ctl := m.ctl
	ctl.mu.Lock()
	b := ctl.beacons[ls.ID]
	if b == nil {
		b = &beacon{}
		ctl.beacons[ls.ID] = b
	}
	wasDone := b.state == stateDone
	b.state, b.at, b.saidStalled = req.State, now, false
	if req.State != stateDone {
		b.saidIdleDone = false
	}
	ctl.mu.Unlock()

	// The tool name and sequence go into the trace, never the arguments.
	data := map[string]any{"state": req.State, "seq": req.Seq, "turns": req.Turns}
	if tool := cleanText(req.Tool, 64); tool != "" {
		data["tool"] = tool
	}
	if req.Tokens > 0 {
		data["tokens_self_reported"] = req.Tokens // not measured: kept apart
	}
	e := api.Event{Type: eventBeacon, Lease: ls.ID, At: now, Data: data}
	m.obs.mu.Lock()
	if l := m.obs.lease(ls.ID); len(l.events) < maxEvents {
		l.events = append(l.events, e)
	}
	m.obs.mu.Unlock()
	if m.obs.audit != nil {
		path, owner, kind := m.scope(ls.ID)
		m.obs.audit.Write(audit.Record{At: now, Type: audit.TypeEvent, Lease: ls.ID, Path: path, Kind: kind, OwnerUID: owner, Event: &e})
	}
	if req.State == stateDone && !wasDone {
		done := map[string]any{}
		if req.Result != "" {
			done["result"] = filepath.Clean(req.Result)
		}
		m.publish(eventDone, ls.ID, done)
	}
	return nil
}

// RequestResize passes a child's request for a larger envelope up to its
// planner as an event. Nothing is changed: the parent decides.
func (m *Manager) RequestResize(c Caller, id api.LeaseID, req api.ResizeAsk) error {
	ls, err := m.resolve(c, id)
	if err != nil {
		return err
	}
	if c.Lease != ls.ID {
		return apiErr(http.StatusForbidden, api.ErrOutOfSubtree, "a lease asks for its own envelope; a planner resizes directly")
	}
	if req.Memory <= ls.Envelope.Memory {
		return invalid("memory", "bytes above the current limit", "", "the request must be for more than the current %d bytes", ls.Envelope.Memory)
	}
	var usage int64
	if rt := m.runtime(ls.ID); rt != nil {
		if u, err := m.be.Sample(context.Background(), rt.group); err == nil {
			usage = u.Memory
		}
	}
	m.publish(eventResizeRequested, ls.ID, map[string]any{"memory": req.Memory, "current_limit": ls.Envelope.Memory, "usage": usage})
	return nil
}

// checkIdle runs once per tick. It tells a planner, once, when a child is
// done but still alive or has been silent for long, and reaps the child
// with 410 when the planner has not dealt with it by the deadline.
//
// Silence is not death: a long generation or a twenty-minute build sends
// no beacon. A lease that never sent one has no adapter and is left to its
// wall-time limit. Waiting for a person is not idleness either.
func (m *Manager) checkIdle() {
	type action struct {
		id    api.LeaseID
		event string
		data  map[string]any
		reap  bool
	}
	var todo []action
	now := time.Now()
	ctl := m.ctl
	ctl.mu.Lock()
	for id, b := range ctl.beacons {
		idle := now.Sub(b.at)
		switch b.state {
		case stateDone:
			if !b.saidIdleDone {
				b.saidIdleDone = true
				todo = append(todo, action{id: id, event: eventIdleDone, data: map[string]any{"deadline": b.at.Add(m.cfg.MaxIdleDone), "then": "the lease is reaped (410)"}})
			}
			if idle >= m.cfg.MaxIdleDone {
				todo = append(todo, action{id: id, reap: true, data: map[string]any{"reason": "done_but_alive", "idle_seconds": idle.Seconds()}})
			}
		case stateWorking:
			if idle >= m.cfg.StallNotice && !b.saidStalled {
				b.saidStalled = true
				todo = append(todo, action{id: id, event: eventStalled, data: map[string]any{"silent_seconds": idle.Seconds(), "deadline": b.at.Add(m.cfg.MaxIdle), "then": "the lease is reaped (410)"}})
			}
			if idle >= m.cfg.MaxIdle {
				todo = append(todo, action{id: id, reap: true, data: map[string]any{"reason": "stalled", "idle_seconds": idle.Seconds()}})
			}
		}
	}
	ctl.mu.Unlock()
	for _, a := range todo {
		if ls, ok := m.led.Get(a.id); !ok || ls.State != api.StateRunning {
			continue
		}
		if a.reap {
			go m.reap(a.id, api.CodeIdleReaped, a.data)
		} else {
			m.publish(a.event, a.id, a.data)
		}
	}
}

// forget drops the control state of an ended lease and settles its scratch
// directory: a nested lease's scratch is kept until its parent ends, so
// that the planner can still fetch the result; everything a lease kept for
// its children goes with the lease.
func (m *Manager) forget(ls api.Lease) {
	ctl := m.ctl
	ctl.mu.Lock()
	if in := ctl.inboxes[ls.ID]; in != nil {
		for ch := range in.subs {
			close(ch)
		}
	}
	delete(ctl.inboxes, ls.ID)
	delete(ctl.beacons, ls.ID)
	var remove []api.LeaseID
	var collect func(id api.LeaseID)
	collect = func(id api.LeaseID) {
		for _, c := range ctl.scratch[id] {
			collect(c)
			remove = append(remove, c)
		}
		delete(ctl.scratch, id)
	}
	collect(ls.ID)
	if ls.Parent == "" {
		remove = append(remove, ls.ID)
	} else {
		ctl.scratch[ls.Parent] = append(ctl.scratch[ls.Parent], ls.ID)
	}
	ctl.mu.Unlock()
	if s, ok := m.be.(backend.Scratcher); ok {
		for _, id := range remove {
			if err := s.RemoveScratch(id); err != nil {
				m.log.Warn("cannot remove a scratch directory", "lease", id, "err", err)
			}
		}
	}
}

// notifyInbox mirrors the events a lease should hear about itself into its
// inbox, from where its adapter injects them into the conversation.
func (m *Manager) notifyInbox(typ string, lease api.LeaseID) {
	switch typ {
	case telemetry.EventNearLimit:
		m.deliver(lease, api.MsgNearLimit, "subactld", "", nil)
	case telemetry.EventResized:
		m.deliver(lease, api.MsgResized, "subactld", "", nil)
	}
}
